import{admitDetachedSourceFamilies}from'./stoppedRuntimeOwners.js';
import{reserveContextPreparation}from'./contextPreparationRegistry.js';
import{captureStoppedRuntime,assertStoppedRuntime,inspectStoppedRuntime,assertDetachedConstruction,verifyRunningNativeClock}from'./stoppedRuntimeSnapshot.js';
/** Exact-edge journal. No broad disconnect, Native method patch or inferred edge. */
export function applyStoppedRuntimeEdges(context,{remove=[],add=[]}={}){
 if(!Array.isArray(remove)||!Array.isArray(add)||remove.length+add.length>96)throw Error('Runtime edge journal capacity exceeded');
 const checked=(edge,list)=>{if(!Array.isArray(edge)||edge.length!==2||!edge[0]||typeof edge[0].connect!=='function'||typeof edge[0].disconnect!=='function'||!edge[1]||edge[0].context!==context||edge[1].context!==context)throw Error('Explicit same-context Native edge required');if(list.some(other=>other!==edge&&other[0]===edge[0]&&other[1]===edge[1]))throw Error('Duplicate Native runtime edge');};
 for(const edge of remove)checked(edge,remove);for(const edge of add)checked(edge,add);for(const a of add)if(remove.some(r=>r[0]===a[0]&&r[1]===a[1]))throw Error('Unchanged Native runtime edge must be omitted');
 const applied=[];let restored=false;
 const restore=()=>{if(restored)return;const errors=[];for(const[operation,from,to]of applied.slice().reverse())try{operation==='connect'?from.disconnect(to):from.connect(to);}catch(error){errors.push(error);}if(errors.length)throw new AggregateError(errors,'Runtime edge rollback failed');restored=true;};
 try{for(const[from,to]of remove){from.disconnect(to);applied.push(['disconnect',from,to]);}for(const[from,to]of add){from.connect(to);applied.push(['connect',from,to]);}}catch(error){try{restore();}catch(rollback){const failure=new AggregateError([error,rollback],'Runtime edge installation and rollback failed');failure.rollbackFailed=true;throw failure;}throw error;}
 return Object.freeze({restore,count:applied.length});
}
/** NEW unselected transaction. Generator alone supplies its future binding seam.
 * Construction callbacks own partial failure cleanup. Returned bundles must have
 * dispose():Promise; shared resources remain explicit upstream leases. */
export function prepareStoppedRuntimeBundle(generator,{prepareEnvironment,sourceClock,buildOwners,isCurrent=()=>true,signal}={}){
 if(typeof prepareEnvironment!=='function'||typeof sourceClock!=='function'||typeof buildOwners!=='function'||typeof isCurrent!=='function')throw Error('Explicit stopped runtime preparation factories required');
 const snapshot=captureStoppedRuntime(generator);admitDetachedSourceFamilies(assertDetachedConstruction(snapshot));
 const released=async work=>{const receipt=await work;if(receipt?.clean===false||receipt?.acknowledged===false||receipt?.released===false||receipt?.quarantined===true)throw Error('Stopped runtime release reported incomplete cleanup');return receipt;};
 const lease=reserveContextPreparation(generator.AC,{label:'stopped-generator-runtime',wake:true,signal,isCurrent});
 let environment,source,bundle,published=null,state='preparing',edges=null,previous=null,committing=false,retirement=null,rollbackError=null,partialCleanupError=null,childDone=Promise.resolve();
 const checked=()=>{assertStoppedRuntime(snapshot);if(!isCurrent())throw Error('Stopped runtime request superseded');if(lease.signal.aborted)throw lease.signal.reason??Error('Stopped runtime request cancelled');};
 const ready=(async()=>{try{await lease.ready;checked();const environmentLease=await lease.track(()=>prepareEnvironment(generator.AC),r=>{if(typeof r?.release!=='function')throw Error('Environment preparation has no explicit release authority');return released(r.release());});if(environmentLease?.context!==generator.AC||!environmentLease.value||typeof environmentLease.release!=='function')throw Error('Explicit same-context environment lease required');environment=environmentLease.value;checked();environment.checkRuntime?.();const clockLease=await lease.track(()=>sourceClock(generator.AC,environment),r=>{if(typeof r?.release!=='function')throw Error('Clock binding has no explicit release authority');return released(r.release());});if(clockLease?.context!==generator.AC||!clockLease.value||typeof clockLease.release!=='function')throw Error('Explicit same-context clock lease required');source=clockLease.value;verifyRunningNativeClock(source,generator.AC);checked();await lease.track(()=>({async dispose(){await childDone;if(partialCleanupError)throw partialCleanupError;if(rollbackError)throw rollbackError;}}),record=>record.dispose());checked();let childSettled;childDone=new Promise(resolve=>childSettled=resolve);let pendingChild;try{pendingChild=lease.track(async()=>{try{const made=await buildOwners({snapshot,environment,signal:lease.signal});if(!made||typeof made.dispose!=='function'){partialCleanupError=Error('Detached owner construction returned no cleanup authority');throw partialCleanupError;}return made;}catch(error){partialCleanupError??=error.cleanupError??null;throw error;}},made=>released(made.dispose()));pendingChild.finally(childSettled).catch(()=>{});bundle=await pendingChild;}catch(error){childSettled();throw error;}checked();state='prepared';return handle;}catch(error){state='failed';try{await lease.cancel(error);}catch(cleanupError){error.cleanupError=cleanupError;}throw error;}})();ready.catch(()=>{});
 const handle=Object.freeze({snapshot,ready,get state(){return state;},describe(){return{version:1,profile:'stopped-generator-runtime-candidate-v1',state,rollbackQuarantined:!!rollbackError,partialCleanupQuarantined:!!partialCleanupError,owners:bundle?.describe?.()??null,source:source?.snapshot?.()??null,reservation:lease.snapshot()};},
  async cancel(reason){if(published)throw Error('Published runtime requires its explicit owner retirement');state='canceling';await lease.cancel(reason);state='closed';},
  async commit(binding){
   await ready;if(state!=='prepared'||committing)throw Error('Stopped runtime is not publishable');if(!binding||binding.version!==1||binding.context!==generator.AC||typeof binding.edges!=='function'||typeof binding.publish!=='function'||typeof binding.retirePrevious!=='function'||typeof binding.preflight!=='function'||typeof binding.restore!=='function'||['preflight','edges','publish','restore'].some(key=>binding[key]?.constructor?.name==='AsyncFunction'))throw Error('Generator-owned stopped runtime binding required');committing=true;
   try{checked();bundle.check?.();verifyRunningNativeClock(source,generator.AC);if(binding.preflight(snapshot,bundle)?.then)throw Error('Runtime preflight must be synchronous');const journal=binding.edges(snapshot,bundle);previous=reserveContextPreparation(generator.AC,{label:'previous-generator-runtime',isCurrent});await previous.ready;checked();bundle.check?.();if(binding.preflight(snapshot,bundle)?.then)throw Error('Runtime preflight must be synchronous');let installed=false;await previous.track(()=>binding,old=>installed?old.retirePrevious():undefined);
    edges=applyStoppedRuntimeEdges(generator.AC,journal);
    published=lease.publish(()=>{try{const value=binding.publish({snapshot,bundle,environment,roleWanderFactory:environment.roleWanderFactory});if(value?.then)throw Error('Generator runtime publication must be synchronous');installed=true;return value;}catch(error){const failures=[error];try{if(binding.restore(snapshot,bundle)?.then)throw Error('Runtime pointer restore must be synchronous');}catch(e){failures.push(e);}try{edges.restore();}catch(e){failures.push(e);}if(failures.length>1){rollbackError=new AggregateError(failures,'Stopped runtime publication rollback failed; context preparation quarantined');throw rollbackError;}throw error;}});
    state='published';retirement=previous.cancel();retirement.catch(()=>{});return Object.freeze({value:published.value,previousRetirement:retirement,scope:published,describe:()=>handle.describe()});
   }catch(error){if(error.rollbackFailed)rollbackError=error;if(!published){if(previous)try{await previous.cancel(error);}catch(cleanup){error.previousCleanupError=cleanup;}try{await lease.cancel(error);}catch(cleanup){error.cleanupError=cleanup;}state='failed';}throw error;}finally{committing=false;}
  }
 });return handle;
}